#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# redacted_reader on both RDB instances (LEDGER D2, D18, D19). For crm,
# then shop: admin connection → drop and apply the hyde-db views → reader
# password and unlock → verify as the reader → <APP>_REDACTED_URL into
# apply.env (gitignored).
#
#   bash scripts/wizard/fetch-redacted-sql.sh
#   bash scripts/wizard/redacted-reader.sh [--dry-run] \
#     .redacted-sql/crm/redacted-views.sql .redacted-sql/shop/redacted-views.sql
#
# Beside each redacted-views.sql must lie redacted-views-drop.sql and ca.pem,
# the instance CA; fetch-redacted-sql.sh puts them there. --dry-run asks
# nothing, runs nothing and writes nothing: it prints every statement, with
# passwords masked. ROTATE=1 generates new reader passwords without asking.
#
# Passwords never reach argv, the terminal or shell history: statements go to
# mysql on stdin, credentials sit in mode-600 option files in a private temp
# directory removed on exit, and the reader's password is written only to
# apply.env. Re-runnable: every step is idempotent, the apply step is always
# drop then apply, and an existing <APP>_REDACTED_URL keeps its password
# unless you rotate. Runbook: docs/runbooks/redacted-reader.md.

TOTAL_STAGES=11

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
ENV_FILE="${APPLY_ENV:-$ROOT/apply.env}"
# VERIFY_CA checks the chain against the app's instance CA, not the host
# name: neither instance certificate names the host we connect to in a way
# every client accepts (crm's names only the instance id).
SSL_MODE="${MYSQL_SSL_MODE:-VERIFY_CA}"
READER=redacted_reader
VIEWS_DB=redacted
DRY_RUN=0

usage() {
  printf 'usage: %s [--dry-run] <crm redacted-views.sql> <shop redacted-views.sql>\n' "$0" >&2
  printf '       fetch both with scripts/wizard/fetch-redacted-sql.sh\n' >&2
  exit 2
}
if [[ "${1:-}" == "--dry-run" ]]; then DRY_RUN=1; shift; fi
[[ $# -eq 2 ]] || usage
CRM_SQL="$1"
SHOP_SQL="$2"

die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

TMP="$(mktemp -d)"
chmod 700 "$TMP"
trap 'rm -rf "$TMP"' EXIT
trap 'exit 130' INT TERM HUP

# 40 random URL-safe characters plus one of each class a password policy may
# require. No quote, backslash, '@' or ':', so it needs no escaping in SQL or
# in the URL.
generate_password() {
  printf 'Aa1-%s' "$(openssl rand -base64 48 | tr -d '\n=+/' | cut -c1-40)"
}

# mask TEXT: TEXT with the admin and reader passwords replaced by ****.
mask() {
  local s="$1"
  if [[ -n "${ADMIN_PW:-}" ]]; then s="${s//"$ADMIN_PW"/****}"; fi
  if [[ -n "${READER_PW:-}" ]]; then s="${s//"$READER_PW"/****}"; fi
  printf '%s' "$s"
}

# write_cnf WHO USER PASSWORD: a mysql option file at $TMP/WHO.cnf, mode 600.
write_cnf() {
  local user="$2" pw="$3"
  user="${user//\\/\\\\}"; user="${user//\"/\\\"}"
  pw="${pw//\\/\\\\}"; pw="${pw//\"/\\\"}"
  (umask 077 && printf '[client]\nuser="%s"\npassword="%s"\n' "$user" "$pw" >"$TMP/$1.cnf")
}

# gate QUESTION: confirm, or yes in a dry run (which shows the question).
gate() {
  if (( DRY_RUN )); then note "(dry run, would ask: $1)"; return 0; fi
  confirm "$1"
}

# mysql_as WHO [args...]: the mysql client as admin or reader, over TLS
# verified against the app's instance CA.
mysql_as() {
  local who="$1"; shift
  mysql --defaults-extra-file="$TMP/$who.cnf" -h "$HOST" -P "$PORT" \
    --ssl-mode="$SSL_MODE" --ssl-ca="$CA" --batch --skip-column-names "$@"
}

# show WHO DB TEXT: what is about to run, passwords masked.
show() {
  local user="$ADMIN_USER"
  if [[ "$1" == reader ]]; then user="$READER"; fi
  printf '  %s$ mysql -u %s -h %s -P %s --ssl-mode=%s --ssl-ca=%s%s%s\n' \
    "$DIM" "$user" "$HOST" "$PORT" "$SSL_MODE" "${CA#"$ROOT"/}" "${2:+ -D $2}" "$RESET"
  printf '      %s\n' "$(mask "$3")"
}

# sql WHO DB STATEMENT: show the statement, then run it, fed on stdin.
sql() {
  show "$1" "$2" "$3"
  if (( DRY_RUN )); then return 0; fi
  if [[ -n "$2" ]]; then
    printf '%s\n' "$3" | mysql_as "$1" -D "$2"
  else
    printf '%s\n' "$3" | mysql_as "$1"
  fi
}

# sql_file DB FILE: run a hyde-db script as the admin, DB as default database.
sql_file() {
  show admin "$1" "< ${2#"$ROOT"/} ($(wc -l <"$2" | tr -d ' ') lines)"
  if (( DRY_RUN )); then return 0; fi
  mysql_as admin -D "$1" <"$2"
}

# app_files APP SQL: checks the three files and reads the first view and its
# source table from the apply script.
app_files() {
  local app="$1" sql="$2" dir line re
  dir="$(cd "$(dirname "$sql")" && pwd)" || die "$app: no directory for $sql"
  [[ -s "$sql" ]] || die "$app: $sql is missing or empty"
  [[ -s "$dir/redacted-views-drop.sql" ]] || die "$app: $dir/redacted-views-drop.sql is missing"
  [[ -s "$dir/ca.pem" ]] || die "$app: $dir/ca.pem is missing (run fetch-redacted-sql.sh)"
  grep -q 'GENERATED by hyde-db' "$sql" || die "$app: $sql is not a hyde-db script"
  # The first model view; the marker view has no column list and is skipped.
  re="VIEW \`$VIEWS_DB\`\\.\`([^\`]+)\` \\([^']* FROM \`([^\`]+)\`;"
  line="$(grep -m1 -E "$re" "$sql")" || die "$app: no view in $sql"
  [[ "$line" =~ $re ]] || die "$app: cannot read the first view of $sql"
  printf -v "${app}_VIEW" '%s' "${BASH_REMATCH[1]}"
  printf -v "${app}_TABLE" '%s' "${BASH_REMATCH[2]}"
  printf -v "${app}_VIEWS" '%s' "$(grep -cE "VIEW \`$VIEWS_DB\`\\.\`[^\`]+\` \\(" "$sql")"
  printf -v "${app}_DIR" '%s' "$dir"
  printf -v "${app}_APPLY" '%s' "$dir/$(basename "$sql")"
}

# ask_default VAR PROMPT DEFAULT: visible input, Enter keeps DEFAULT. A dry
# run takes the default without asking.
ask_default() {
  local input=""
  if (( DRY_RUN )); then printf -v "$1" '%s' "$3"; note "$2 $3"; return 0; fi
  read -e -r -p "  $2 [$3] " input || true
  printf -v "$1" '%s' "${input:-$3}"
}

# Per app, filled by app_files through printf -v.
crm_VIEW="" crm_TABLE="" crm_VIEWS="" crm_DIR="" crm_APPLY=""
shop_VIEW="" shop_TABLE="" shop_VIEWS="" shop_DIR="" shop_APPLY=""

# The app now being configured. Set by select_app.
APP="" KEY="" HOST="" PORT="" DB="" CA="" ADMIN_USER="" ADMIN_PW="" READER_PW=""
VIEW="" TABLE="" VIEWS="" APPLY="" DROP="" VERIFIED=0

select_app() {
  APP="$1"
  case "$APP" in
    crm)
      KEY=CRM_REDACTED_URL
      HOST=rw-0001.example.invalid PORT=3307 DB=crm-prod
      VIEW="$crm_VIEW" TABLE="$crm_TABLE" VIEWS="$crm_VIEWS" APPLY="$crm_APPLY" CA="$crm_DIR/ca.pem" ;;
    shop)
      KEY=SHOP_REDACTED_URL
      HOST=rw-0000.example.invalid PORT=3306 DB=shop
      VIEW="$shop_VIEW" TABLE="$shop_TABLE" VIEWS="$shop_VIEWS" APPLY="$shop_APPLY" CA="$shop_DIR/ca.pem" ;;
  esac
  DROP="$(dirname "$APPLY")/redacted-views-drop.sql"
  ADMIN_USER="" ADMIN_PW="" READER_PW="" VERIFIED=0
}

# The reader's password: the one in apply.env's existing URL, unless the
# human rotates (or ROTATE=1); otherwise a new one.
choose_reader_password() {
  local current re="^mysql://$READER:([A-Za-z0-9-]+)@"
  current="$(_existing "$KEY" || true)"
  READER_PW=""
  if [[ "$current" =~ $re ]]; then READER_PW="${BASH_REMATCH[1]}"; fi
  if [[ -n "$READER_PW" ]]; then
    say "$KEY exists in ${ENV_FILE#"$ROOT"/}: its password is set again, unchanged."
    if [[ "${ROTATE:-0}" == 1 ]]; then
      READER_PW=""
    elif (( ! DRY_RUN )) && confirm "Rotate instead, with a new password?"; then
      READER_PW=""
    fi
  fi
  if [[ -z "$READER_PW" ]]; then
    READER_PW="$(generate_password)"
    say "A new password is generated; it is shown nowhere and lands only in $KEY."
  fi
}

reader_url() { printf 'mysql://%s:%s@%s:%s/%s?ssl=true' "$READER" "$READER_PW" "$HOST" "$PORT" "$VIEWS_DB"; }

# ── Stages ────────────────────────────────────────────────────────────────

# A dry run waits for nobody.
if (( DRY_RUN )); then pause() { :; }; fi

banner "redacted_reader on crm and shop"
if (( DRY_RUN )); then warn "dry run: nothing is asked, run or written"; fi

stage "Preconditions"
say "Runs on your machine. For each app you need an admin account on its RDB"
say "instance that can create users, views and grants and read mysql.*."
app_files crm "$CRM_SQL"
app_files shop "$SHOP_SQL"
say "${GREEN}✓${RESET} crm: $crm_VIEWS views, first \`$VIEWS_DB\`.\`$crm_VIEW\` from \`$crm_TABLE\`"
say "${GREEN}✓${RESET} shop: $shop_VIEWS views, first \`$VIEWS_DB\`.\`$shop_VIEW\` from \`$shop_TABLE\`"
if ! command -v mysql >/dev/null 2>&1; then
  if (( DRY_RUN )); then warn "mysql client not found (fine for a dry run)"; else die "install the MySQL client: brew install mysql-client"; fi
elif mysql --version 2>/dev/null | grep -qi mariadb; then
  if (( DRY_RUN )); then warn "this is the MariaDB client; the run needs MySQL's (--ssl-mode)"; else die "the MariaDB client lacks --ssl-mode; install MySQL's: brew install mysql-client"; fi
else
  say "${GREEN}✓${RESET} $(mysql --version)"
fi
command -v openssl >/dev/null 2>&1 || die "openssl is needed to generate the reader password"
note "Connection strings go to ${ENV_FILE#"$ROOT"/} (gitignored, mode 600)."
pause "Continue?"

configure_app() {
  select_app "$1"

  stage "$APP: admin connection"
  say "The admin login on $APP's instance. Host name, not IP: the TLS check needs it."
  ask_default HOST "Host:" "$HOST"
  if [[ "$HOST" =~ ^[0-9.]+$ || "$HOST" == *:* ]]; then die "$HOST is an address; give the rw-<instance-id> host name"; fi
  ask_default PORT "Port:" "$PORT"
  ask_default DB "Source database:" "$DB"
  if (( DRY_RUN )); then
    ADMIN_USER="<admin>"
  else
    ask ADMIN_USER "Admin user:"
    [[ -n "$ADMIN_USER" ]] || die "an admin user is needed"
    ask_secret ADMIN_PW "Password for $ADMIN_USER (hidden):"
    write_cnf admin "$ADMIN_USER" "$ADMIN_PW"
  fi
  say "Read-only check of login, default database and TLS:"
  if gate "Connect to $APP now?"; then
    sql admin "$DB" "SELECT CURRENT_USER(), DATABASE(); SHOW SESSION STATUS LIKE 'Ssl_cipher';" \
      || die "admin login failed; check host, port, user and password, then re-run"
  else
    note "skipped $APP; re-run the wizard to configure it"
    SKIPPED+=("$APP: the whole app")
    _STAGE_INDEX=$((_STAGE_INDEX + 4))
    return 0
  fi
  pause

  stage "$APP: drop and apply the redacted views"
  say "As $ADMIN_USER, default database $DB, in this order:"
  step "redacted-views-drop.sql: revokes $READER's grants, drops database $VIEWS_DB"
  step "redacted-views.sql: recreates $VIEWS_DB with $VIEWS views, creates $READER"
  say "  locked and without password if missing, grants SELECT on the views"
  note "Idempotent: a re-run drops and applies again. Without --force, so a refusal"
  note "stops it; it prints 'hyde-db: <problem> Fix: <statement>'. Paste the fix as"
  note "an admin, then re-run."
  if gate "Drop and apply on $APP now?"; then
    sql_file "$DB" "$DROP" || die "drop refused; apply its printed fix, then re-run"
    sql_file "$DB" "$APPLY" || die "apply refused; apply its printed fix, then re-run"
    if (( ! DRY_RUN )); then say "${GREEN}✓${RESET} views applied"; fi
  else
    note "skipped: the views stay as they are"
  fi
  pause

  stage "$APP: reader password and unlock"
  choose_reader_password
  say "Sets the password, requires TLS for every reader login and unlocks it."
  say "The apply script never touches either again, so this survives re-applies."
  if gate "Set the password and unlock $READER on $APP now?"; then
    sql admin "" "ALTER USER '$READER'@'%' IDENTIFIED BY '$READER_PW' REQUIRE SSL ACCOUNT UNLOCK;" \
      || die "ALTER USER failed; is $READER missing? Run the apply stage first"
    local expected=$'N\tANY' state=$'N\tANY'
    show admin "" "SELECT account_locked, ssl_type FROM mysql.user WHERE user = '$READER' AND host = '%';   -- expect: N ANY"
    if (( ! DRY_RUN )); then
      state="$(printf '%s\n' "SELECT account_locked, ssl_type FROM mysql.user WHERE user = '$READER' AND host = '%';" | mysql_as admin)"
    fi
    [[ "$state" == "$expected" ]] || die "$READER is not unlocked with REQUIRE SSL: got '$state'"
    if (( ! DRY_RUN )); then say "${GREEN}✓${RESET} $READER unlocked, TLS required"; fi
  else
    note "skipped: verify below needs the password in $KEY to be the one set"
  fi
  pause

  stage "$APP: verify as $READER"
  say "Logs in as $READER over TLS. Read-only. Must hold, in order:"
  step "the session is encrypted (Ssl_cipher not empty)"
  step "SELECT on the view \`$VIEWS_DB\`.\`$VIEW\` succeeds"
  step "SELECT on the table \`$DB\`.\`$TABLE\` is refused (ERROR 1142)"
  if (( ! DRY_RUN )); then write_cnf reader "$READER" "$READER_PW"; fi
  gate "Verify $APP now?" || die "not skippable: $KEY is written only after it passes"
  local out=""
  sql reader "" "SHOW SESSION STATUS LIKE 'Ssl_cipher';"
  if (( ! DRY_RUN )); then
    out="$(printf '%s\n' "SHOW SESSION STATUS LIKE 'Ssl_cipher';" | mysql_as reader 2>&1)" \
      || die "reader login failed: $(mask "$out")"
    [[ "$(printf '%s' "$out" | cut -f2)" =~ [A-Za-z] ]] || die "no TLS cipher on the reader session"
    say "${GREEN}✓${RESET} TLS: $(printf '%s' "$out" | cut -f2)"
  fi
  show reader "" "SELECT 1 FROM \`$VIEWS_DB\`.\`$VIEW\` LIMIT 1;   -- must succeed"
  if (( ! DRY_RUN )); then
    out="$(printf '%s\n' "SELECT 1 FROM \`$VIEWS_DB\`.\`$VIEW\` LIMIT 1;" | mysql_as reader 2>&1)" \
      || die "the view is not readable: $(mask "$out")"
    say "${GREEN}✓${RESET} view readable"
  fi
  show reader "" "SELECT 1 FROM \`$DB\`.\`$TABLE\` LIMIT 1;   -- must be refused"
  if (( ! DRY_RUN )); then
    if out="$(printf '%s\n' "SELECT 1 FROM \`$DB\`.\`$TABLE\` LIMIT 1;" | mysql_as reader 2>&1)"; then
      die "$READER can read \`$DB\`.\`$TABLE\`: its grants are too broad; re-run the apply stage"
    fi
    [[ "$out" == *"ERROR 1142"* ]] || die "refused, but not for privilege: $(mask "$out")"
    say "${GREEN}✓${RESET} table refused: $(mask "$out")"
  fi
  VERIFIED=1
  pause

  stage "$APP: write $KEY"
  say "hyde-mcp-gateway's connection string for $APP, TLS as the apps' runtime strings:"
  note "$KEY='$(mask "$(reader_url)")'"
  if (( ! VERIFIED )); then die "not verified"; fi
  if gate "Write $KEY to ${ENV_FILE#"$ROOT"/} now?"; then
    if (( DRY_RUN )); then
      note "(dry run, not written)"
    else
      write_env "$KEY" "$(reader_url)"
    fi
  else
    SKIPPED+=("$KEY: re-run the wizard (Enter keeps the password)")
  fi
  pause
}

configure_app crm
configure_app shop

finish
if (( DRY_RUN )); then note "dry run: nothing ran, nothing was written"; fi
note "Next: the runtime verifies the server against each app's instance CA (ssl=true)."
note "After every migration: drop → migrate → apply (docs/runbooks/redacted-reader.md)."
